class Solution {
public:
    std::string largestPalindromic(std::string num) {
        std::vector<int> counts(10, 0);
        for (char ch : num) counts[ch - '0']++;
        std::string first_half = "";
        for (int d = 9; d >= 0; --d) {
            if (d == 0 && first_half.empty()) continue;
            int pairs = counts[d] / 2;
            if (pairs > 0) {
                first_half.append(pairs, '0' + d);
                counts[d] %= 2;
            }
        }
        std::string mid = "";
        for (int d = 9; d >= 0; --d) {
            if (counts[d] > 0) {
                mid += ('0' + d);
                break;
            }
        }
        std::string second_half = first_half;
        std::reverse(second_half.begin(), second_half.end());
        std::string ans = first_half + mid + second_half;
        return ans.empty() ? "0" : ans;
    }
};

class Solution {
    public String largestPalindromic(String num) {
        int[] counts = new int[10];
        for (int i = 0; i < num.length(); ++i) counts[num.charAt(i) - '0']++;
        StringBuilder firstHalf = new StringBuilder();
        for (int d = 9; d >= 0; --d) {
            if (d == 0 && firstHalf.length() == 0) continue;
            int pairs = counts[d] / 2;
            if (pairs > 0) {
                for (int p = 0; p < pairs; ++p) firstHalf.append(d);
                counts[d] %= 2;
            }
        }
        String mid = "";
        for (int d = 9; d >= 0; --d) {
            if (counts[d] > 0) {
                mid = Integer.toString(d);
                break;
            }
        }
        String firstStr = firstHalf.toString();
        String secondStr = new StringBuilder(firstStr).reverse().toString();
        String ans = firstStr + mid + secondStr;
        return ans.isEmpty() ? "0" : ans;
    }
}

var largestPalindromic = function(num) {
    const counts = new Array(10).fill(0);
    for (let i = 0; i < num.length; ++i) counts[num.charCodeAt(i) - 48]++;
    let firstHalf = '';
    for (let d = 9; d >= 0; --d) {
        if (d === 0 && firstHalf.length === 0) continue;
        const pairs = Math.floor(counts[d] / 2);
        if (pairs > 0) {
            firstHalf += String(d).repeat(pairs);
            counts[d] %= 2;
        }
    }
    let mid = '';
    for (let d = 9; d >= 0; --d) {
        if (counts[d] > 0) {
            mid = String(d);
            break;
        }
    }
    const secondHalf = firstHalf.split('').reverse().join('');
    const ans = firstHalf + mid + secondHalf;
    return ans.length > 0 ? ans : '0';
};
